-- How many proofs a claim has, raised by one at a time (not on a SETTLED or VOID claim, nor one
-- dated in a closed period). A claim whose due is above the sheet's proof threshold in force on its
-- date cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
# Add a proof to a claim: its proofs count goes up by one. A SETTLED or VOID claim, or one dated in a
# closed period, is a 409 and writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimProof
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimProof
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimProofAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Remind an OPEN or PENDING claim: it shows the sheet's today as its reminded date. Once per
# sheet-today: a second reminder the same day, or a claim in any other status, is a 409 and writes
# nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimRemind
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimRemind
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimReminded
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused reminder writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaimProof {
    public void validate(@RequestBody ClaimProofRequest request, Out<ClaimProof> body, Out<Actor> actor) {
        String user = request == null ? null : request.user();
        actor.set(new Actor(user));
        body.set(new ClaimProof(user));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one. A SETTLED or VOID claim, or one dated in a closed period, is refused. */
public class ApplyClaimProof {
    public void apply(@Val ClaimProof change, @Val Claim claim, ClosedPeriods closedPeriods)
            throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDueBy());
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ClaimStatusRefusedException("A proof cannot be added to a " + claim.getStatus() + " claim");
        }
        claim.setProofs(claim.getProofs() + 1);
    }
}
package net.officefloor.hq.app.claim;

/** A validated proof added to a claim: who adds it. */
public record ClaimProof(String user) {
}
package net.officefloor.hq.app.claim;

/** Body of adding a proof to a claim: who adds it. */
public record ClaimProofRequest(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused proof writes no audit line. */
public class RecordClaimProofAdded {
    public void record(@Val ClaimProof change, @Val Claim claim, People people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record("CLAIM_PROOF_ADDED sheet=" + claim.getSheetId() + " by=" + change.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + " proofs=" + claim.getProofs());
    }
}

